pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    function testFuzz_property(uint256 initialSupply, string memory tokenName, string memory tokenSymbol, address owner, uint256 mintAmount, address target, uint256 burnAmount) public {
        // Bound initialSupply and mintAmount to avoid overflow
        vm.assume(initialSupply <= 1e50);
        vm.assume(mintAmount <= 1e50);
        // Restrict burnAmount to be less than or equal to mintAmount+initialSupply to ensure balance is sufficient
        vm.assume(burnAmount <= initialSupply + mintAmount);
        // Ensure target is not address(0)
        vm.assume(target != address(0));
        // Ensure owner is not address(0) and distinct from target (to avoid collision in balance calculations)
        vm.assume(owner != address(0));
        vm.assume(owner != target);

        // Deploy a new C with the fuzzed parameters, as set up uses empty constructor (0,0,0)
        c = new C(initialSupply, tokenName, tokenSymbol);

        // As the owner, mint tokens to target
        vm.prank(owner);
        c.mintToken(target, mintAmount);

        // Record balances and total supply before burn
        uint256 balanceOwnerBefore = c.balanceOf(owner);
        uint256 balanceTargetBefore = c.balanceOf(target);
        uint256 totalSupplyBefore = c.totalSupply();

        // Burn from owner (owner is the only one with initialSupply, plus they received totalSupply originally)
        // However, if initialSupply is 0 and minted to target only, owner might have no balance. We need to ensure we burn from a non-frozen account with balance.
        // We'll assume owner burns; if owner has no balance, we skip the burn or transfer via mint?
        // To simplify, we ensure the owner has balance by not freezing and using the existing supply.
        // We'll just try to burn; if revert, we catch it, but the invariant should hold only on successful burns.
        // We wrap in try/catch to handle possible reverts gracefully.
        bool burnSucceeded = false;
        vm.prank(owner);
        try c.burn(burnAmount) {
            burnSucceeded = true;
        } catch {
            burnSucceeded = false;
        }

        // If burn succeeded, compute expected total supply reduction and verify sum invariant.
        // The invariant: totalSupply == sum of all balances (known accounts).
        // Since we only have two accounts, we can sum them.
        uint256 sumBalancesAfter = c.balanceOf(owner) + c.balanceOf(target);
        uint256 totalSupplyAfter = c.totalSupply();
        if (burnSucceeded) {
            // In the correct contract, totalSupplyAfter should be totalSupplyBefore - burnAmount.
            // However, the more robust invariant is that totalSupply == sum of all balances.
            // The buggy version lacks totalSupply decrement, so sumBalances decreases but totalSupply stays same.
            assertTrue(sumBalancesAfter == totalSupplyAfter);
        } else {
            // If burn reverted, nothing should have changed.
            assertTrue(c.balanceOf(owner) == balanceOwnerBefore);
            assertTrue(c.balanceOf(target) == balanceTargetBefore);
            assertTrue(c.totalSupply() == totalSupplyBefore);
        }
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) public { c = _c; }
    function test(address target, uint256 amount) public returns (bool) {
